//! Test-only connection between the wire representation (`dashu_int::UBig`)
//! and the read-only algorithm crate `i2r_candidate`.
//!
//! Source correspondence:
//!   Model.observe input = (case input of [m,n] => [Primrec.ack m n] | _ => [])
//!   Kernel.kernel_prepare input = (case input of [m,n] => (m,n) | _ => (0,0))
//!   Kernel.kernel_run p = (case p of (m,n) => Primrec.ack m n)
//!   Kernel.kernel_encode n = [n]

use dashu_int::UBig;

pub use i2r_candidate::numbers::Nat;

/// Wire integer type used by the connection.
pub type WireInt = UBig;

/// Algorithm-ready input for `kernel_run`: the source pair `(m, n)` as `Nat`s.
///
/// The source `kernel_prepare` produces a `nat * nat`; here the two `nat`s are
/// materialized as the algorithm's `Nat` datatype so that `kernel_run` performs
/// no wire-to-algorithm conversion.
pub struct Prepared {
    pub m: Nat,
    pub n: Nat,
}

/// Raw algorithm result of `kernel_run`: a `Nat`.
pub type KernelResult = Nat;

/// Convert a nonnegative `UBig` into the algorithm's `Nat` (unary `Suc` chain).
///
/// This is a wire-to-algorithm representation conversion and is only used in
/// preparation / encoding, never inside `benchmark_run`.
fn ubig_to_nat(x: &UBig) -> Nat {
    let mut n = i2r_candidate::zero_nat();
    let mut i = UBig::ZERO;
    while i < *x {
        n = i2r_candidate::suc(n);
        i += UBig::ONE;
    }
    n
}

/// Convert the algorithm's `Nat` back into a `UBig` (count of `Suc` layers).
fn nat_to_ubig(n: &Nat) -> UBig {
    let mut acc = UBig::ZERO;
    let mut cur = n;
    while let Some(pred) = cur.pred() {
        acc += UBig::ONE;
        cur = pred;
    }
    acc
}

/// `Model.observe`:
///   observe [m,n] = [ack m n]
///   observe _     = []
///
/// The wire values are converted to the algorithm's `Nat` representation,
/// `ack` is invoked, and the result is converted back to the wire type.
pub fn observe(input: &[WireInt]) -> Vec<WireInt> {
    match input {
        [m, n] => {
            let am = ubig_to_nat(m);
            let an = ubig_to_nat(n);
            let r = i2r_candidate::ack(am, an);
            vec![nat_to_ubig(&r)]
        }
        _ => Vec::new(),
    }
}

/// `Kernel.kernel_prepare`:
///   kernel_prepare [m,n] = (m,n)
///   kernel_prepare _     = (0,0)
///
/// The wire values are converted to the algorithm's `Nat` representation here,
/// before timing, so that `benchmark_run` performs no conversion.
pub fn benchmark_prepare(input: &[WireInt]) -> Prepared {
    match input {
        [m, n] => Prepared {
            m: ubig_to_nat(m),
            n: ubig_to_nat(n),
        },
        _ => Prepared {
            m: i2r_candidate::zero_nat(),
            n: i2r_candidate::zero_nat(),
        },
    }
}

/// `Kernel.kernel_run`:
///   kernel_run (m,n) = ack m n
///
/// Invokes the algorithm directly on the prepared `Nat` values and returns the
/// raw algorithm result. No wire conversion, formatting, or encoding occurs.
pub fn benchmark_run(prepared: Prepared) -> KernelResult {
    i2r_candidate::ack(prepared.m, prepared.n)
}

/// `Kernel.kernel_encode`:
///   kernel_encode n = [n]
///
/// Converts the raw algorithm result to the wire type and wraps it in a
/// singleton list.
pub fn benchmark_encode(result: KernelResult) -> Vec<WireInt> {
    vec![nat_to_ubig(&result)]
}

