//! Rust realization of Isabelle/AFP `Primrec.ack` (Ackermanns_not_PR.Primrec).
//!
//! `Nat.nat` is an inductive datatype with constructors `zero_nat` and `Suc`,
//! so it is represented as a recursive enum rather than a machine integer.
//! The numeric policy (arbitrary/checked integers) does not apply: no
//! mathematical integer arithmetic occurs in the source equations.

pub mod numbers;

pub use numbers::{ack, one_nat, zero_nat, Nat};

algorithm_files.src/numbers.rs:
//! Representation of `Nat.nat` and the Ackermann function `Primrec.ack`.

/// Isabelle `Nat.nat`: an inductive datatype with constructors
/// `zero_nat_inst.zero_nat` and `Nat.Suc`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Nat {
    /// `Nat.zero_nat_inst.zero_nat`
    Zero,
    /// `Nat.Suc`
    Suc(Box<Nat>),
}

impl Nat {
    /// Constructor `Nat.Suc`.
    pub fn suc(n: Nat) -> Nat {
        Nat::Suc(Box::new(n))
    }

    /// Predecessor view: `None` for `zero_nat`, `Some(m)` for `Suc m`.
    pub fn pred(&self) -> Option<&Nat> {
        match self {
            Nat::Zero => None,
            Nat::Suc(m) => Some(m),
        }
    }
}

/// `Nat.zero_nat_inst.zero_nat`
pub fn zero_nat() -> Nat {
    Nat::Zero
}

/// `Nat.one_nat_inst.one_nat` = `Suc zero_nat_inst.zero_nat`
pub fn one_nat() -> Nat {
    Nat::Suc(Box::new(Nat::Zero))
}

/// `Primrec.ack`
///
/// ```text
/// ack 0       n       = Suc n
/// ack (Suc m) 0       = ack m 1
/// ack (Suc m) (Suc n) = ack m (ack (Suc m) n)
/// ```
///
/// Total on `Nat.nat`; recursion is well-founded under the lexicographic
/// order on the argument pair.
pub fn ack(m: Nat, n: Nat) -> Nat {
    match m {
        Nat::Zero => Nat::Suc(Box::new(n)),
        Nat::Suc(box_m) => match n {
            Nat::Zero => ack(*box_m, one_nat()),
            Nat::Suc(box_n) => {
                let inner = ack(Nat::Suc(box_m.clone()), *box_n);
                ack(*box_m, inner)
            }
        },
    }
}
